CREATE TABLE IF NOT EXISTS migrations(version int PRIMARY KEY);
DO $$ BEGIN CREATE ROLE mga_app LOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password text NOT NULL, role text NOT NULL CHECK(role IN ('System Administrator','School Administrator','Laboratory Manager','Laboratory Assistant','Faculty/Staff')), labs uuid[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token text PRIMARY KEY,user_id uuid REFERENCES users, expires timestamptz NOT NULL);
CREATE TABLE login_attempts(key text PRIMARY KEY, attempts int NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE laboratories(id uuid PRIMARY KEY,name text NOT NULL UNIQUE,profile jsonb NOT NULL DEFAULT '{}',archived boolean NOT NULL DEFAULT false);
CREATE TABLE items(id uuid PRIMARY KEY,sku text NOT NULL UNIQUE,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('Durable','Consumable')),category text NOT NULL,unit_cost numeric(14,2) NOT NULL CHECK(unit_cost>=0),details jsonb NOT NULL DEFAULT '{}',archived boolean NOT NULL DEFAULT false);
CREATE TABLE purchases(id uuid PRIMARY KEY,lab_id uuid REFERENCES laboratories NOT NULL,item_id uuid REFERENCES items NOT NULL,qty int NOT NULL CHECK(qty>0),unit_cost numeric(14,2) NOT NULL CHECK(unit_cost>=0),received int NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=qty),status text NOT NULL DEFAULT 'Requested' CHECK(status IN ('Requested','Approved','Ordered','Received','Rejected','Cancelled')),requested_by uuid REFERENCES users NOT NULL,approved_by uuid REFERENCES users,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE receipts(id uuid PRIMARY KEY,purchase_id uuid REFERENCES purchases NOT NULL,qty int NOT NULL CHECK(qty>0),actor uuid REFERENCES users NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE movements(id uuid PRIMARY KEY,item_id uuid REFERENCES items NOT NULL,lab_id uuid REFERENCES laboratories NOT NULL,delta int NOT NULL CHECK(delta<>0),kind text NOT NULL,reference text NOT NULL,actor uuid REFERENCES users NOT NULL,related_id uuid REFERENCES movements,receipt_id uuid REFERENCES receipts UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id bigserial PRIMARY KEY,actor uuid,action text NOT NULL,record_id text,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON movements(item_id,lab_id);
CREATE INDEX ON movements(created_at);
CREATE OR REPLACE FUNCTION current_actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION actor_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM users WHERE id=current_actor() AND active $$;
CREATE OR REPLACE FUNCTION is_admin() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(actor_role() IN ('System Administrator','School Administrator'),false) $$;
CREATE OR REPLACE FUNCTION can_lab(lab uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT active AND (role IN ('System Administrator','School Administrator') OR lab=ANY(labs)) FROM users WHERE id=current_actor()),false) $$;
CREATE OR REPLACE FUNCTION can_write(lab uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT can_lab(lab) AND actor_role()<>'Faculty/Staff' $$;
ALTER TABLE laboratories ENABLE ROW LEVEL SECURITY;
CREATE POLICY lab_read ON laboratories FOR SELECT USING (current_actor() IS NOT NULL);
CREATE POLICY lab_write ON laboratories FOR ALL USING (can_write(id)) WITH CHECK (is_admin() OR (can_write(id) AND NOT archived));
ALTER TABLE items ENABLE ROW LEVEL SECURITY;
CREATE POLICY item_read ON items FOR SELECT USING (current_actor() IS NOT NULL);
CREATE POLICY item_write ON items FOR ALL USING (actor_role()<>'Faculty/Staff') WITH CHECK (actor_role()<>'Faculty/Staff');
ALTER TABLE movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY move_read ON movements FOR SELECT USING (can_lab(lab_id) OR actor_role()='Faculty/Staff');
CREATE POLICY move_insert ON movements FOR INSERT WITH CHECK (can_write(lab_id) AND actor=current_actor());
ALTER TABLE purchases ENABLE ROW LEVEL SECURITY;
CREATE POLICY purchase_read ON purchases FOR SELECT USING (can_lab(lab_id) OR actor_role()='Faculty/Staff');
CREATE POLICY purchase_insert ON purchases FOR INSERT WITH CHECK ((can_lab(lab_id) OR actor_role()='Faculty/Staff') AND requested_by=current_actor() AND status='Requested' AND received=0);
CREATE POLICY purchase_update ON purchases FOR UPDATE USING (can_write(lab_id)) WITH CHECK (can_write(lab_id));
ALTER TABLE receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipt_read ON receipts FOR SELECT USING (EXISTS(SELECT 1 FROM purchases p WHERE p.id=purchase_id));
CREATE POLICY receipt_insert ON receipts FOR INSERT WITH CHECK (actor=current_actor() AND EXISTS(SELECT 1 FROM purchases p WHERE p.id=purchase_id AND can_write(p.lab_id)));
ALTER TABLE audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON audit FOR SELECT USING (is_admin());
CREATE OR REPLACE FUNCTION immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is immutable'; END $$;
CREATE TRIGGER movement_immutable BEFORE UPDATE OR DELETE ON movements FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE TRIGGER receipt_immutable BEFORE UPDATE OR DELETE ON receipts FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE OR REPLACE FUNCTION check_movement() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE balance bigint; old_move movements; used int; item_kind text; BEGIN
IF current_user='mga_app' THEN
 IF NEW.actor IS DISTINCT FROM current_actor() OR NOT can_write(NEW.lab_id) THEN RAISE EXCEPTION 'Unauthorized transaction'; END IF;
 IF EXISTS(SELECT 1 FROM laboratories WHERE id=NEW.lab_id AND archived) OR EXISTS(SELECT 1 FROM items WHERE id=NEW.item_id AND archived) THEN RAISE EXCEPTION 'Archived record'; END IF;
END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.item_id::text||NEW.lab_id::text,0));
SELECT coalesce(sum(delta),0) INTO balance FROM movements WHERE item_id=NEW.item_id AND lab_id=NEW.lab_id;
IF balance+NEW.delta<0 THEN RAISE EXCEPTION 'Insufficient stock'; END IF;
IF NEW.kind='Return' THEN
 SELECT * INTO old_move FROM movements WHERE id=NEW.related_id;
 IF old_move.kind IS DISTINCT FROM 'Checkout' OR old_move.item_id<>NEW.item_id OR old_move.lab_id<>NEW.lab_id OR NEW.delta<=0 THEN RAISE EXCEPTION 'Invalid checkout reference'; END IF;
 SELECT coalesce(sum(delta),0) INTO used FROM movements WHERE related_id=NEW.related_id AND kind='Return';
 IF used+NEW.delta> -old_move.delta THEN RAISE EXCEPTION 'Return exceeds checkout'; END IF;
END IF;
RETURN NEW; END $$;
CREATE TRIGGER movement_guard BEFORE INSERT ON movements FOR EACH ROW EXECUTE FUNCTION check_movement();
CREATE OR REPLACE FUNCTION check_purchase() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF current_user='mga_app' THEN
 IF NEW.lab_id<>OLD.lab_id OR NEW.item_id<>OLD.item_id OR NEW.qty<>OLD.qty OR NEW.unit_cost<>OLD.unit_cost OR NEW.requested_by<>OLD.requested_by THEN RAISE EXCEPTION 'Order terms immutable'; END IF;
 IF OLD.status='Requested' AND NEW.status IN ('Approved','Rejected') THEN
  IF NOT is_admin() OR OLD.requested_by=current_actor() THEN RAISE EXCEPTION 'Independent administrator approval required'; END IF;
 ELSIF OLD.status='Approved' AND NEW.status='Ordered' THEN
  IF actor_role() NOT IN ('System Administrator','School Administrator','Laboratory Manager') THEN RAISE EXCEPTION 'Manager required'; END IF;
 ELSIF OLD.status='Ordered' AND NEW.status IN ('Ordered','Received') AND NEW.received>OLD.received THEN NULL;
 ELSIF OLD.status IN ('Requested','Approved') AND NEW.status='Cancelled' AND NEW.received=0 THEN NULL;
 ELSE RAISE EXCEPTION 'Invalid purchase transition'; END IF;
END IF;
RETURN NEW; END $$;
CREATE TRIGGER purchase_guard BEFORE UPDATE ON purchases FOR EACH ROW EXECUTE FUNCTION check_purchase();
CREATE OR REPLACE FUNCTION write_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO audit(actor,action,record_id,detail) VALUES(current_actor(),TG_TABLE_NAME||':'||TG_OP,NEW.id::text,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER lab_audit AFTER INSERT OR UPDATE ON laboratories FOR EACH ROW EXECUTE FUNCTION write_audit();
CREATE TRIGGER item_audit AFTER INSERT OR UPDATE ON items FOR EACH ROW EXECUTE FUNCTION write_audit();
CREATE TRIGGER movement_audit AFTER INSERT ON movements FOR EACH ROW EXECUTE FUNCTION write_audit();
CREATE TRIGGER purchase_audit AFTER INSERT OR UPDATE ON purchases FOR EACH ROW EXECUTE FUNCTION write_audit();
CREATE TRIGGER receipt_audit AFTER INSERT ON receipts FOR EACH ROW EXECUTE FUNCTION write_audit();
GRANT USAGE ON SCHEMA public TO mga_app;
GRANT SELECT,INSERT,UPDATE ON users,sessions,login_attempts TO mga_app;
GRANT DELETE ON sessions TO mga_app;
GRANT SELECT,INSERT,UPDATE ON laboratories,items,purchases TO mga_app;
GRANT SELECT,INSERT ON movements,receipts TO mga_app;
GRANT SELECT ON audit TO mga_app;
INSERT INTO migrations VALUES(1);
GRANT DELETE ON login_attempts TO mga_app;
CREATE OR REPLACE FUNCTION guard_users() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_user='mga_app' AND (actor_role() IS DISTINCT FROM 'System Administrator' OR (TG_OP='UPDATE' AND OLD.id=current_actor())) THEN RAISE EXCEPTION 'System Administrator required; cannot modify own privileges'; END IF; RETURN NEW; END $$;
CREATE TRIGGER user_guard BEFORE INSERT OR UPDATE ON users FOR EACH ROW EXECUTE FUNCTION guard_users();
CREATE OR REPLACE FUNCTION user_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO audit(actor,action,record_id,detail) VALUES(current_actor(),'users:'||TG_OP,NEW.id::text,to_jsonb(NEW)-'password'); RETURN NEW; END $$;
CREATE TRIGGER user_change_audit AFTER INSERT OR UPDATE ON users FOR EACH ROW EXECUTE FUNCTION user_audit();
CREATE OR REPLACE FUNCTION item_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_user='mga_app' AND NOT is_admin() THEN RAISE EXCEPTION 'Administrator required to edit shared item definition'; END IF; RETURN NEW; END $$;
CREATE TRIGGER item_change_guard BEFORE UPDATE ON items FOR EACH ROW EXECUTE FUNCTION item_guard();
CREATE OR REPLACE FUNCTION receipt_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p purchases; total int; BEGIN SELECT * INTO p FROM purchases WHERE id=NEW.purchase_id FOR UPDATE; IF p.status<>'Ordered' THEN RAISE EXCEPTION 'Only ordered purchases may be received'; END IF; SELECT coalesce(sum(qty),0) INTO total FROM receipts WHERE purchase_id=p.id; IF total+NEW.qty>p.qty THEN RAISE EXCEPTION 'Cannot overreceive'; END IF; RETURN NEW; END $$;
CREATE TRIGGER receipt_guard BEFORE INSERT ON receipts FOR EACH ROW EXECUTE FUNCTION receipt_guard();
CREATE OR REPLACE FUNCTION reconcile_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE r receipts; p purchases; count_moves int; BEGIN SELECT * INTO r FROM receipts WHERE id=NEW.id; SELECT * INTO p FROM purchases WHERE id=r.purchase_id; SELECT count(*) INTO count_moves FROM movements WHERE receipt_id=r.id AND item_id=p.item_id AND lab_id=p.lab_id AND delta=r.qty AND kind='Purchase received'; IF count_moves<>1 OR p.received<>(SELECT coalesce(sum(qty),0) FROM receipts WHERE purchase_id=p.id) THEN RAISE EXCEPTION 'Receipt must reconcile to order and inventory'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER receipt_reconciliation AFTER INSERT ON receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION reconcile_receipt();
CREATE OR REPLACE FUNCTION validate_move_type() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF NEW.kind NOT IN ('Opening','Return','Adjustment increase','Transfer in','Purchase received','Usage','Checkout','Transfer','Loss','Damage','Retirement','Adjustment decrease') THEN RAISE EXCEPTION 'Unknown movement type'; END IF;
IF (NEW.kind IN ('Opening','Return','Adjustment increase','Transfer in','Purchase received')) IS DISTINCT FROM (NEW.delta>0) THEN RAISE EXCEPTION 'Invalid movement sign'; END IF;
IF NEW.kind='Purchase received' AND NEW.receipt_id IS NULL THEN RAISE EXCEPTION 'Receipt required'; END IF;
IF current_user='mga_app' AND NEW.kind='Adjustment increase' AND NOT (is_admin() OR actor_role()='Laboratory Manager') THEN RAISE EXCEPTION 'Manager required'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER movement_type_guard BEFORE INSERT ON movements FOR EACH ROW EXECUTE FUNCTION validate_move_type();
